const v1 = document.getElementById('video-with-tracks');
const w1 = document.getElementById('wrapper-1');
if (!v1 || !w1) return false;

if (!document.getElementById('ai4a11y-caption-helper-styles')) return true;

const btn = w1.querySelector('.ai4a11y-audio-btn');
if (!btn) return false;

const rect = btn.getBoundingClientRect();
return rect.right <= 320 && rect.left >= 0 && rect.width >= 24 && rect.height >= 24;

const w2 = document.getElementById('wrapper-2');
if (!w2) return false;

if (!document.getElementById('ai4a11y-caption-helper-styles')) return true;

const btn2 = w2.querySelector('.ai4a11y-audio-btn');
const box2 = w2.querySelector('.ai4a11y-caption-box');
if (!btn2 || !box2) return false;

btn2.click();
await new Promise(r => setTimeout(r, 60));

const ok = btn2.getAttribute('aria-pressed') === 'true' && box2.style.display === 'block';

btn2.click();
return ok && btn2.getAttribute('aria-pressed') === 'false';
